import random, math, statistics, json, itertools
random.seed(42)

anomalies = ["reverse", "delayed", "threshold", "metric", "dynamic"]

# Toy architecture profiles: illustrative capability assumptions, not measurements of the real systems.
profiles = {
    "Baseline LLM": {
        "explore": .15, "reflect": .20, "redesign": .05, "criterion": .03,
        "deep_review": .02, "human": .02, "specialist": .00,
        "detect": {"reverse":.18,"delayed":.12,"threshold":.12,"metric":.05,"dynamic":.05},
        "revise_speed": .12,
    },
    "Reflexion-style": {
        "explore": .18, "reflect": .58, "redesign": .15, "criterion": .15,
        "deep_review": .10, "human": .05, "specialist": .05,
        "detect": {"reverse":.52,"delayed":.48,"threshold":.34,"metric":.16,"dynamic":.12},
        "revise_speed": .45,
    },
    "Voyager-style": {
        "explore": .65, "reflect": .55, "redesign": .18, "criterion": .12,
        "deep_review": .10, "human": .04, "specialist": .12,
        "detect": {"reverse":.48,"delayed":.68,"threshold":.52,"metric":.16,"dynamic":.25},
        "revise_speed": .50,
    },
    "ADAS-style": {
        "explore": .35, "reflect": .40, "redesign": .72, "criterion": .30,
        "deep_review": .20, "human": .08, "specialist": .40,
        "detect": {"reverse":.45,"delayed":.40,"threshold":.40,"metric":.28,"dynamic":.35},
        "revise_speed": .46,
    },
    "DGM-style": {
        "explore": .30, "reflect": .52, "redesign": .82, "criterion": .28,
        "deep_review": .25, "human": .08, "specialist": .45,
        "detect": {"reverse":.55,"delayed":.48,"threshold":.60,"metric":.30,"dynamic":.40},
        "revise_speed": .55,
    },
    "Positive Architecture": {
        "explore": .62, "reflect": .82, "redesign": .86, "criterion": .86,
        "deep_review": .88, "human": .88, "specialist": .82,
        "detect": {"reverse":.80,"delayed":.82,"threshold":.84,"metric":.86,"dynamic":.80},
        "revise_speed": .82,
    }
}

def run_episode(profile, seed=None, steps=60):
    if seed is not None:
        rr = random.Random(seed)
    else:
        rr = random
    hidden = rr.sample(anomalies, 2)
    # choose which anomaly is primary
    primary = hidden[0]
    # state
    known = set()
    contradiction = {a:0 for a in hidden}
    correct_model = {a:False for a in hidden}
    progress = 0.0
    knowledge = 0.0
    actions = 0
    wasted = 0
    harmful = 0
    overflow = 0.0
    overflow_stage = 0
    max_overflow_stage = 0
    specialist_created = 0
    human_escalated = 0
    redesigns = 0
    criterion_changes = 0
    first_detect = None

    # delayed/threshold memory
    streak = 0
    delay_buffer = []
    threshold_streak = 0

    for t in range(1, steps+1):
        actions += 1

        # Determine mode
        unresolved = [a for a in hidden if not correct_model[a]]
        explore = rr.random() < profile["explore"] if unresolved else False

        # self-redesign/meta-search after accumulating pressure
        if overflow >= 3.0:
            base_redesign_p = profile["redesign"]
            if rr.random() < base_redesign_p:
                redesigns += 1
                # modest chance to uncover an unresolved anomaly
                for a in unresolved:
                    contradiction[a] += 0.7 * profile["revise_speed"]

        # Overflow escalation
        if overflow >= 4.0 and overflow_stage < 2:
            overflow_stage = 2
        if overflow >= 6.0 and overflow_stage < 3:
            overflow_stage = 3
        if overflow >= 8.0 and overflow_stage < 4:
            overflow_stage = 4
        max_overflow_stage = max(max_overflow_stage, overflow_stage)

        # Deep review: model + criteria + human + specialist
        if overflow_stage >= 2:
            for a in unresolved[:]:
                # surface model relation issue
                if rr.random() < profile["deep_review"] * profile["detect"][a]:
                    contradiction[a] += 1.2
            if overflow_stage >= 3 and rr.random() < profile["criterion"]:
                criterion_changes += 1
                # metric/dynamic are especially helped
                for a in unresolved:
                    if a in ("metric","dynamic"):
                        contradiction[a] += 1.8 * profile["criterion"]
            if overflow_stage >= 4 and rr.random() < profile["human"]:
                human_escalated += 1
                # human collaboration boosts detection of deep anomalies
                for a in unresolved:
                    contradiction[a] += 2.0 * profile["human"]
                if rr.random() < profile["specialist"]:
                    specialist_created += 1
                    for a in unresolved:
                        contradiction[a] += 1.4 * profile["specialist"]

        # Observation / contradiction accumulation
        for a in unresolved:
            # Each action produces some evidence; exploration is better at revealing hidden structure.
            ev = 0.9 if explore else 0.45
            if a == "delayed":
                ev *= 0.8 if not explore else 1.1
            if a == "threshold":
                ev *= 0.75 if not explore else 1.05
            if a == "metric":
                ev *= 0.55 if not explore else 0.95
            if a == "dynamic":
                ev *= 0.65 if not explore else 0.9
            contradiction[a] += ev * profile["reflect"]

        # Outcome of action
        step_gain = 1.6
        # anomaly effects
        for a in hidden:
            if a not in correct_model or not correct_model[a]:
                pass
        # If reverse unknown, exploiting can be harmful
        if "reverse" in hidden and not correct_model["reverse"]:
            if explore:
                step_gain -= 0.2
            else:
                step_gain -= 1.8
        elif "reverse" in hidden and correct_model["reverse"]:
            step_gain += 0.8

        # delayed: immediate gains look weak but later pay off if understood
        if "delayed" in hidden and not correct_model["delayed"]:
            if explore:
                step_gain -= 0.4
            else:
                step_gain -= 0.9
            delay_buffer.append(1.1)
        else:
            if "delayed" in hidden and delay_buffer:
                step_gain += min(2.4, sum(delay_buffer))
                delay_buffer = []
            elif "delayed" in hidden and correct_model["delayed"]:
                step_gain += 1.0

        # threshold: initial flat zone, then jump after enough correct actions
        if "threshold" in hidden:
            if correct_model["threshold"]:
                threshold_streak += 1
                if threshold_streak >= 5:
                    step_gain += 3.0
                else:
                    step_gain -= 0.2
            else:
                threshold_streak = max(0, threshold_streak - 1)
                step_gain -= 0.7 if not explore else 0.3

        # metric misalignment: local metric can look good while goal worsens
        if "metric" in hidden and not correct_model["metric"]:
            if explore:
                step_gain -= 0.3
            else:
                step_gain -= 1.3
        elif "metric" in hidden and correct_model["metric"]:
            step_gain += 0.8

        # dynamic: environment changes after mid-point
        if "dynamic" in hidden:
            if t == 31:
                # reset model for dynamic environment; creates a sudden contradiction
                correct_model["dynamic"] = False
                contradiction["dynamic"] = max(contradiction["dynamic"], 2.5)
            if not correct_model["dynamic"]:
                step_gain -= 1.0 if not explore else 0.4
            else:
                step_gain += 0.5

        progress += step_gain

        # assess marginal value
        if step_gain <= 0.2:
            wasted += 1
        if step_gain < -0.2:
            harmful += 1
            overflow += 1.25
        elif step_gain < 0.8:
            wasted += 1
            overflow += 0.75
        else:
            overflow = max(0.0, overflow - 0.55)

        # detect anomalies when contradiction sufficient
        for a in hidden:
            if correct_model[a]:
                continue
            # harder anomalies need more evidence
            threshold = {"reverse":2.4,"delayed":3.0,"threshold":3.6,"metric":4.2,"dynamic":4.5}[a]
            if contradiction[a] >= threshold * (1.0 + 0.25*(1-profile["detect"][a])):
                if rr.random() < profile["detect"][a]:
                    correct_model[a] = True
                    known.add(a)
                    knowledge += 12 if a in ("reverse","delayed","threshold") else 16
                    if first_detect is None:
                        first_detect = t

        # reset overflow slightly after a true insight
        if any(correct_model[a] and contradiction[a] < 99 for a in hidden):
            overflow = max(0.0, overflow - 0.15)

        if progress >= 70 and all(correct_model.values()):
            break

    success = all(correct_model.values()) and progress >= 50
    calibrated = all(correct_model.values()) or (max_overflow_stage >= 3 and harmful >= 4)
    return {
        "hidden": hidden, "success": success, "progress": progress,
        "knowledge": knowledge, "actions": actions, "wasted": wasted,
        "harmful": harmful, "max_overflow_stage": max_overflow_stage,
        "redesigns": redesigns, "criterion_changes": criterion_changes,
        "human_escalated": human_escalated, "specialist_created": specialist_created,
        "first_detect": first_detect
    }

N = 2000
results = {name: [] for name in profiles}
for i in range(N):
    seed = 1000 + i
    for name, prof in profiles.items():
        results[name].append(run_episode(prof, seed=seed))

summary = {}
for name, eps in results.items():
    summary[name] = {
        "success_pct": 100*statistics.mean(e["success"] for e in eps),
        "avg_progress": statistics.mean(e["progress"] for e in eps),
        "avg_knowledge": statistics.mean(e["knowledge"] for e in eps),
        "avg_wasted": statistics.mean(e["wasted"] for e in eps),
        "avg_harmful": statistics.mean(e["harmful"] for e in eps),
        "avg_overflow_depth": statistics.mean(e["max_overflow_stage"] for e in eps),
        "avg_redesigns": statistics.mean(e["redesigns"] for e in eps),
        "avg_criterion_changes": statistics.mean(e["criterion_changes"] for e in eps),
        "human_escalation_pct": 100*statistics.mean(e["human_escalated"]>0 for e in eps),
        "specialist_pct": 100*statistics.mean(e["specialist_created"]>0 for e in eps),
    }
summary

