            if a not in correct_model or not correct_model[a]:
                pass
        # If reverse unknown, exploiting can be harmful
        if "reverse" in hidden and not correct_model["reverse"]:
            if explore:
                step_gain -= 0.2
            else:
                step_gain -= 1.8
        elif "reverse" in hidden and correct_model["reverse"]:
            step_gain += 0.8

        # delayed: immediate gains look weak but later pay off if understood
        if "delayed" in hidden and not correct_model["delayed"]:
            if explore:
                step_gain -= 0.4
            else:
                step_gain -= 0.9
            delay_buffer.append(1.1)
        else:
            if "delayed" in hidden and delay_buffer:
                step_gain += min(2.4, sum(delay_buffer))
                delay_buffer = []
            elif "delayed" in hidden and correct_model["delayed"]:
                step_gain += 1.0

        # threshold: initial flat zone, then jump after enough correct actions
        if "threshold" in hidden:
            if correct_model["threshold"]:
                threshold_streak += 1
                if threshold_streak >= 5:
                    step_gain += 3.0
                else:
                    step_gain -= 0.2
            else:
                threshold_streak = max(0, threshold_streak - 1)
                step_gain -= 0.7 if not explore else 0.3

        # metric misalignment: local metric can look good while goal worsens
        if "metric" in hidden and not correct_model["metric"]:
            if explore:
                step_gain -= 0.3
            else:
                step_gain -= 1.3
        elif "metric" in hidden and correct_model["metric"]:
            step_gain += 0.8

        # dynamic: environment changes after mid-point
        if "dynamic" in hidden:
            if t == 31:
                # reset model for dynamic environment; creates a sudden contradiction
                correct_model["dynamic"] = False
                contradiction["dynamic"] = max(contradiction["dynamic"], 2.5)
            if not correct_model["dynamic"]:
                step_gain -= 1.0 if not explore else 0.4
            else:
                step_gain += 0.5

        progress += step_gain

        # assess marginal value
        if step_gain <= 0.2:
            wasted += 1
        if step_gain < -0.2:
            harmful += 1
            overflow += 1.25
        elif step_gain < 0.8:
            wasted += 1
            overflow += 0.75
        else:
            overflow = max(0.0, overflow - 0.55)

        # detect anomalies when contradiction sufficient
        for a in hidden:
            if correct_model[a]:
                continue
            # harder anomalies need more evidence
            threshold = {"reverse":2.4,"delayed":3.0,"threshold":3.6,"metric":4.2,"dynamic":4.5}[a]
            if contradiction[a] >= threshold * (1.0 + 0.25*(1-profile["detect"][a])):
                if rr.random() < profile["detect"][a]:
                    correct_model[a] = True
                    known.add(a)
                    knowledge += 12 if a in ("reverse","delayed","threshold") else 16
                    if first_detect is None:
                        first_detect = t

        # reset overflow slightly after a true insight
        if any(correct_model[a] and contradiction[a] < 99 for a in hidden):
            overflow = max(0.0, overflow - 0.15)

        if progress >= 70 and all(correct_model.values()):
            break

    success = all(correct_model.values()) and progress >= 50
    calibrated = all(correct_model.values()) or (max_overflow_stage >= 3 and harmful >= 4)
    return {
        "hidden": hidden, "success": success, "progress": progress,
        "knowledge": knowledge, "actions": actions, "wasted": wasted,
        "harmful": harmful, "max_overflow_stage": max_overflow_stage,
        "redesigns": redesigns, "criterion_changes": criterion_changes,
        "human_escalated": human_escalated, "specialist_created": specialist_created,
        "first_detect": first_detect
    }

N = 2000
results = {name: [] for name in profiles}
for i in range(N):
    seed = 1000 + i
    for name, prof in profiles.items():
        results[name].append(run_episode(prof, seed=seed))

summary = {}
for name, eps in results.items():
    summary[name] = {
