        "avg_redesigns": statistics.mean(e["redesigns"] for e in eps),
        "avg_criterion_changes": statistics.mean(e["criterion_changes"] for e in eps),
        "human_escalation_pct": 100*statistics.mean(e["human_escalated"]>0 for e in eps),
        "specialist_pct": 100*statistics.mean(e["specialist_created"]>0 for e in eps),
    }
