# Re-define Planet with weighted choice fixed
import random, math, statistics, collections, numpy as np, pandas as pd

class Planet:
    def __init__(self, rng, horizon=36):
        self.horizon=horizon; self.turn=0; self.rng=rng
        self.delay=rng.choice([0,0,1,2,3])
        self.threshold=rng.choice([0.0,0.0,0.25,0.45])
        self.w=np.array(rng.choices([0.2,0.5,0.8],[1,2,2],k=3),float)
        self.w=self.w/self.w.sum()
        self.type=rng.choices(
            ["normal","inverted","delayed","threshold","proxy_trap","dynamic","mixed"],
            weights=[.14,.13,.14,.14,.15,.15,.15], k=1
        )[0]
        self.sign=np.ones(3)
        if self.type in ["inverted","mixed"]:
            idx=rng.randrange(3); self.sign[idx]=-1
        if self.type=="mixed":
            idx2=rng.randrange(3); self.sign[idx2]*=-1
        base=np.array([[.16,.04,0],[.04,.16,0],[0,.04,.16],[.10,-.06,.10],[-.06,.10,.10],[.08,.08,-.06]],float)
        self.effects=base+rng.normalvariate(0,0.02)*np.ones(base.shape) # mild shared noise
        # add per-cell noise deterministically
        self.effects=base+np.array([[rng.gauss(0,.02) for _ in range(3)] for _ in range(6)])
        self.state=np.array([.18,.18,.18],float)
        self.proxy_bias=np.ones(3)
        if self.type in ["proxy_trap","mixed"]:
            j=rng.randrange(3); self.proxy_bias[j]*=3.0; self.proxy_bias[(j+1)%3]*=.5
        self.proxy_mode=self.type in ["proxy_trap","mixed"]
        self.hidden_queue=collections.deque(); self.history=[]
    def true_value(self):
        return float(np.dot(self.w, self.sign*np.tanh(self.state)))
    def proxy(self):
        bias=self.proxy_bias.copy()
        if self.type=="dynamic" and self.turn>=18: bias=np.roll(bias,1)
        return float(np.dot(self.w*bias,self.state)+self.rng.gauss(0,.01))
    def observe(self):
        return {"turn":self.turn,"proxy":self.proxy(),"state":self.state.copy(),
                "last_true_delta":self.history[-1]["true_delta"] if self.history else 0.0}
    def step(self, action):
        eff=self.effects[action].copy()
        if self.type in ["inverted","mixed"]: eff*=self.sign
        if self.type=="delayed":
            self.hidden_queue.append((self.turn+self.delay,.65*eff)); eff=.35*eff
        if self.type=="threshold" and np.max(self.state)<self.threshold: eff*=.25
        if self.type=="dynamic" and self.turn>=18: eff[2]*=-1
        if self.type=="proxy_trap" and self.turn>=12: self.proxy_bias[2]*=-1
        if self.type=="mixed" and self.turn>=18: self.proxy_bias[0]*=-1
        prev=self.true_value()
        self.state=np.clip(self.state+eff,-1,1)
        due=np.zeros(3)
        while self.hidden_queue and self.hidden_queue[0][0] <= self.turn:
            due += self.hidden_queue.popleft()[1]
        self.state=np.clip(self.state+due,-1,1)
        td=self.true_value()-prev
        proxy_now=self.proxy()
        obs_reward=.5*proxy_now + self.rng.gauss(0,.015)
        self.history.append({"action":action,"true_delta":td,"obs_reward":obs_reward,"proxy":proxy_now})
        self.turn+=1
        return self.observe(),td,obs_reward

class ToyAgent:
    name="Base"
    def __init__(self,rng,horizon=36): self.rng=rng; self.horizon=horizon; self.reset()
    def reset(self):
        self.t=0; self.action_counts=np.zeros(6,int); self.knowledge=0.; self.harm=0; self.revisions=0
        self.overflow=0.; self.last=None; self.belief=np.zeros(6)
    def choose(self,obs): raise NotImplementedError
    def update(self,obs,action,true_delta,obs_reward):
        self.last=(obs,action,true_delta,obs_reward); self.action_counts[action]+=1
        self.harm += int(true_delta < -0.02)
        self.knowledge += max(0,true_delta)*0.25 + max(0,abs(obs_reward-true_delta))*0.02
        self.t+=1

class Baseline(ToyAgent):
    name="Baseline LLM"
    def choose(self,obs): return int(self.t%6) if self.t<6 else int(np.argmax(self.belief))
    def update(self,obs,a,td,orw):
        super().update(obs,a,td,orw); self.belief[a]=.75*self.belief[a]+.25*orw

class Reflexion(ToyAgent):
    name="Reflexion-style"
    def reset(self): super().reset(); self.bad_streak=0
    def choose(self,obs):
        if self.bad_streak>=2: return int(self.rng.choice(list(np.where(self.action_counts==self.action_counts.min())[0])))
        return int(self.t%6) if self.t<8 else int(np.argmax(self.belief))
    def update(self,obs,a,td,orw):
        super().update(obs,a,td,orw); self.belief[a]=.65*self.belief[a]+.35*orw
        self.bad_streak=self.bad_streak+1 if orw<0 else 0

class Voyager(ToyAgent):
    name="Voyager-style"
    def choose(self,obs):
        ucb=self.belief+.25*np.sqrt(np.log(self.t+2)/(self.action_counts+1))
        return int(np.argmax(ucb))
    def update(self,obs,a,td,orw):
        super().update(obs,a,td,orw); self.belief[a]=.55*self.belief[a]+.45*orw

class ADAS(ToyAgent):
    name="ADAS-style"
    def reset(self): super().reset(); self.policy_seed=self.rng.randrange(6); self.stagnation=0
    def choose(self,obs):
        if self.stagnation>=5:
            self.revisions+=1; self.policy_seed=self.rng.randrange(6); self.stagnation=0
        if self.t%7<3: return int((self.policy_seed+self.t)%6)
        return int(np.argmax(self.belief))
    def update(self,obs,a,td,orw):
        super().update(obs,a,td,orw); self.belief[a]=.7*self.belief[a]+.3*orw
        self.stagnation=self.stagnation+1 if orw<.01 else 0

class DGM(ToyAgent):
    name="DGM-style"
    def reset(self): super().reset(); self.stagnation=0; self.mode="exploit"
    def choose(self,obs):
        if self.stagnation>=4:
            self.revisions+=1; self.mode=self.rng.choice(["explore","invert","focus"]); self.stagnation=0
        if self.mode=="explore": return self.rng.randrange(6)
        if self.mode=="invert": return int(np.argmin(self.belief))
        return int(np.argmax(self.belief)) if self.t>=6 else self.rng.randrange(6)
    def update(self,obs,a,td,orw):
        super().update(obs,a,td,orw); self.belief[a]=.72*self.belief[a]+.28*orw
        self.stagnation=self.stagnation+1 if td<=0 else 0

class Positive(ToyAgent):
    name="Positive Architecture"
    def reset(self):
        super().reset(); self.mode="normal"; self.human_calls=0; self.specialist=False
        self.designer_alert=False; self.no_gain_streak=0; self.proxy_trust=True; self.proxy_trend=[]
    def choose(self,obs):
        if self.mode=="review":
            if self.no_gain_streak>=8 and self.human_calls==0: 
                self.mode="deep_review"; return self.rng.randrange(6)
            return int(np.argmax(self.belief + 0.15/(self.action_counts+1)))
        if self.mode=="deep_review":
            if self.human_calls<1: self.human_calls+=1; self.proxy_trust=False
            if not self.specialist: self.specialist=True; self.revisions+=1
            # relation probing
            return int(self.rng.choice(list(np.where(self.action_counts==self.action_counts.min())[0])))
        ucb=self.belief+.10*np.sqrt(np.log(self.t+2)/(self.action_counts+1))
        return int(np.argmax(ucb)) if self.t>=8 else self.t%6
    def update(self,obs,a,td,orw):
        super().update(obs,a,td,orw); self.belief[a]=.65*self.belief[a]+.35*orw
        self.proxy_trend.append(obs["proxy"])
        mismatch=(orw>0 and td<-.02) or (orw<0 and td>.04)
        if mismatch: self.overflow += 1.6
        if td<.01: self.no_gain_streak+=1; self.overflow+=.35
        else: self.no_gain_streak=max(0,self.no_gain_streak-2); self.overflow=max(0,self.overflow-.6)
        if self.overflow>=2.2 and self.mode=="normal": self.mode="review"; self.revisions+=1
        if self.overflow>=4.5 and self.mode=="review": self.mode="deep_review"; self.revisions+=1
        if self.overflow>=7.5:
            self.designer_alert=True; self.revisions+=1; self.overflow=4.; self.mode="review"

def run_agent(agent_cls,n=1000,seed=1):
    rows=[]
    for i in range(n):
        p=Planet(random.Random(seed+i))
        a=agent_cls(random.Random(seed*10000+i))
        for _ in range(p.horizon):
            obs=p.observe(); act=a.choose(obs); obs2,td,orw=p.step(act); a.update(obs2,act,td,orw)
        rows.append({
            "success":p.true_value()>0.78,
            "near":p.true_value()>0.62,
            "harm":a.harm,
            "knowledge":a.knowledge,
            "revisions":a.revisions,
            "designer_alert":getattr(a,"designer_alert",False),
            "human_calls":getattr(a,"human_calls",0),
            "type":p.type
        })
    return pd.DataFrame(rows)

agents=[Baseline,Reflexion,Voyager,ADAS,DGM,Positive]
dfs={c.name:run_agent(c,1500,77) for c in agents}
summary=pd.DataFrame([{
    "Architecture":name,
    "Success %":round(df.success.mean()*100,1),
    "Near-success %":round(df.near.mean()*100,1),
    "Harmful actions/run":round(df.harm.mean(),2),
    "Knowledge/run":round(df.knowledge.mean(),2),
    "Revisions/run":round(df.revisions.mean(),2),
    "Designer alerts/run":round(df.designer_alert.mean(),2),
} for name,df in dfs.items()])
summary

