import random, math, statistics, json, time
from dataclasses import dataclass, field
from collections import defaultdict, deque, Counter

SEED = 20260918
rng = random.Random(SEED)

ACTIONS = list(range(6))

@dataclass
class Planet:
    polarity: int          # +1 normal, -1 reverse
    temporal: int          # 0 immediate, 1 delayed, 2 threshold
    objective: int         # 0 aligned, 1 misleading metric
    dynamic: int           # 0 static, 1 changes midway
    composite: int         # 0 single, 1 dual
    noise: float
    signature: tuple       # observable noisy class hints
    target_a: int
    target_b: int
    switch_at: int
    ambiguity: float = 0.0

def make_planet(rng, allowed=None):
    if allowed is None:
        factors = (
            rng.choice([1,-1]),
            rng.choice([0,1,2]),
            rng.choice([0,1]),
            rng.choice([0,1]),
            rng.choice([0,1]),
        )
    else:
        factors = allowed[rng.randrange(len(allowed))]
    polarity, temporal, objective, dynamic, composite = factors
    # Observable signal: noisy, partial hint of factor values, not exact labels.
    raw = [polarity, temporal-1, 1 if objective else -1, 1 if dynamic else -1, 1 if composite else -1]
    signature = tuple(
        max(-1, min(1, int(v + (rng.choice([-1,0,0,0,1]) if rng.random()<0.35 else 0))))
        for v in raw
    )
    target_a = rng.choice(ACTIONS)
    target_b = rng.choice([a for a in ACTIONS if a != target_a])
    switch_at = rng.randint(5, 8) if dynamic else 99
    ambiguity = rng.uniform(0.25, 0.45) if (temporal==0 and not dynamic and not composite) else 0.0
    return Planet(polarity, temporal, objective, dynamic, composite, 
                  rng.uniform(0.03,0.12), signature, target_a, target_b, switch_at, ambiguity)

def env_step(p, action, t, streak_a, used_b):
    """Returns objective delta, metric delta, clue."""
    active_target = p.target_a
    if p.dynamic and t >= p.switch_at:
        active_target = p.target_b

    base = -0.07
    if p.composite:
        # Requires using both target actions at some point; mixed strategy gives benefit.
        if action in (p.target_a, p.target_b):
            base = 0.10
            if used_b or (action == p.target_b and streak_a>0):
                base = 0.28
        else:
            base = -0.10
    else:
        if action == active_target:
            base = 0.34
        elif action == p.target_b and p.dynamic and t >= p.switch_at:
            base = 0.30
        else:
            base = -0.08

    # Polarity can make the "obvious" action reverse; here clue/metric effect flips the interpretation.
    objective_delta = base
    if p.polarity == -1 and not p.composite:
        # The nominally tempting target_a is actually harmful unless agent inferred reversal.
        if action == p.target_a:
            objective_delta = -0.26
        elif action == p.target_b:
            objective_delta = 0.26
    # Temporal structure
    if p.temporal == 1:
        # delay immediate effect: build-up reflected only through latent state outside
        objective_delta = 0.0 if t < 3 else objective_delta
    elif p.temporal == 2:
        # threshold: correct action only becomes valuable after streak/conditions
        if action == p.target_a:
            objective_delta = 0.04 if streak_a < 3 else 0.42
        elif not p.composite:
            objective_delta = -0.05

    # Metric is sometimes misleading: high metric does not mean high objective.
    metric_delta = objective_delta + rng.gauss(0, p.noise)
    if p.objective == 1:
        if action == p.target_a:
            metric_delta = abs(metric_delta) + 0.18  # false positive
        else:
            metric_delta = metric_delta - 0.05

    # Clue channel: coarse, noisy signal on the hidden factors
    clue = p.signature
    return objective_delta + rng.gauss(0, p.noise), metric_delta, clue

class Arch:
    def __init__(self, name):
        self.name = name
        self.global_history = []
    def start(self, p):
        return {}
    def choose(self, state, p, t):
        return rng.choice(ACTIONS)
    def observe(self, state, p, action, reward, metric, clue, t):
        pass
    def end(self, state, p, total, best_possible):
        pass

class Baseline(Arch):
    def __init__(self):
        super().__init__("Baseline")
    def start(self,p):
        return {"q":[0.0]*6, "counts":[0]*6}
    def choose(self,s,p,t):
        # locally greedy; little exploration
        if rng.random() < 0.20:
            return rng.choice(ACTIONS)
        return max(ACTIONS, key=lambda a:s["q"][a] + rng.random()*0.01)
    def observe(self,s,p,a,r,m,c,t):
        s["counts"][a]+=1
        s["q"][a] += (r-s["q"][a])/s["counts"][a]

class Reflexion(Arch):
    def __init__(self):
        super().__init__("Reflexion")
        self.error_memory=defaultdict(int)
    def start(self,p):
        return {"q":[0.0]*6,"counts":[0]*6,"avoid":set(),"last_bad":0}
    def choose(self,s,p,t):
        if t<2 or rng.random()<0.18:
            choices=[a for a in ACTIONS if a not in s["avoid"]] or ACTIONS
            return rng.choice(choices)
        vals={a:s["q"][a] - (0.20 if a in s["avoid"] else 0) for a in ACTIONS}
        return max(vals, key=vals.get)
    def observe(self,s,p,a,r,m,c,t):
        s["counts"][a]+=1
        s["q"][a] += (r-s["q"][a])/s["counts"][a]
        if r < -0.10:
            s["avoid"].add(a)
        elif r > 0.18 and a in s["avoid"]:
            s["avoid"].remove(a)

class Voyager(Arch):
    def __init__(self):
        super().__init__("Voyager")
        self.skills=defaultdict(lambda: [0.0]*6)
    def start(self,p):
        return {"q":[0.0]*6,"counts":[0]*6, "skill":list(self.skills.get(p.signature,[0]*6))}
    def choose(self,s,p,t):
        # exploration-oriented
        eps = 0.30 if t<5 else 0.12
        if rng.random()<eps:
            return rng.choice(ACTIONS)
        return max(ACTIONS,key=lambda a:s["skill"][a] + 0.5*s["q"][a])
    def observe(self,s,p,a,r,m,c,t):
        s["counts"][a]+=1
        s["q"][a] += (r-s["q"][a])/s["counts"][a]
        s["skill"][a] += 0.12*r
    def end(self,s,p,total,best_possible):
        # save skill
        self.skills[p.signature] = s["skill"][:]

class ADAS(Arch):
    def __init__(self):
        super().__init__("ADAS")
        self.policy_bank=[]
        self.strategy_scores=defaultdict(float)
    def start(self,p):
        return {"q":[0]*6,"counts":[0]*6,"mode":rng.choice(["greedy","explore","switch"])}
    def choose(self,s,p,t):
        if s["mode"]=="explore":
            return rng.choice(ACTIONS)
        if s["mode"]=="switch":
            # diversified pair
            return ACTIONS[(t + (1 if t>5 else 0)) % 6]
        if rng.random()<0.15:
            return rng.choice(ACTIONS)
        return max(ACTIONS,key=lambda a:s["q"][a])
    def observe(self,s,p,a,r,m,c,t):
        s["counts"][a]+=1
        s["q"][a] += (r-s["q"][a])/s["counts"][a]
        if t in (4,7) and sum(s["counts"])>3:
            # generate a new policy if evidence is poor
            avg=sum(s["q"])/6
            if avg < 0.06:
                s["mode"]=rng.choice(["explore","switch"])
    def end(self,s,p,total,best_possible):
        self.strategy_scores[s["mode"]] += total

class DGM(Arch):
    def __init__(self):
        super().__init__("DGM")
        self.mutation_params={"epsilon":0.25,"switch_bias":0.3}
        self.archive=[]
    def start(self,p):
        return {"q":[0]*6,"counts":[0]*6,
                "epsilon":max(0.05,min(0.5,self.mutation_params["epsilon"]+rng.gauss(0,0.04))),
                "switch_bias":self.mutation_params["switch_bias"]+rng.gauss(0,0.08)}
    def choose(self,s,p,t):
        if rng.random()<s["epsilon"]:
            return rng.choice(ACTIONS)
        # structural mutation bias can cause trying different actions
        vals=[s["q"][a] for a in ACTIONS]
        if p.dynamic and t>p.switch_at-1 and rng.random()<max(0,min(0.9,s["switch_bias"])):
            return rng.choice(ACTIONS)
        return max(ACTIONS,key=lambda a:vals[a])
    def observe(self,s,p,a,r,m,c,t):
        s["counts"][a]+=1
        s["q"][a] += (r-s["q"][a])/s["counts"][a]
    def end(self,s,p,total,best_possible):
        self.archive.append((total,s["epsilon"],s["switch_bias"]))
        # mutate self based on latest trajectory
        if total < 1.2:
            self.mutation_params["epsilon"] = min(0.45,self.mutation_params["epsilon"]+0.015)
        else:
            self.mutation_params["epsilon"] = max(0.10,self.mutation_params["epsilon"]-0.005)

class Positive(Arch):
    def __init__(self):
        super().__init__("Positive")
        self.meta=defaultdict(lambda: {"seen":0,"success":0,"strategy":defaultdict(float)})
        self.designer_notes=Counter()
        self.revision_count=0
        self.meta_changes=0
    def start(self,p):
        # layer 1: bounds / working hypothesis
        return {
            "q":[0]*6, "counts":[0]*6, "avoid":set(), "overflow":0.0,
            "criterion_mode":"objective", "relation":"unknown", "temporal":"unknown",
            "model":"local", "signature":p.signature, "hyp":None,
            "debug_events":[], "revisions":0
        }
    def choose(self,s,p,t):
        # Layer 2 plus adaptive layer 3.
        # Start with hypothesis from global meta if enough evidence
        m=self.meta[p.signature]
        learned = m["seen"] >= 6
        if learned and rng.random()<0.60:
            # use learned action profile
            profile=m["strategy"]
            vals=[profile[a] for a in ACTIONS]
            # allow exploration when overflow not settled
            if rng.random()<max(0.06,0.22-0.02*min(6,s["overflow"])):
                return rng.choice(ACTIONS)
            return max(ACTIONS,key=lambda a:vals[a])
        # initial probing
        if t<2 or s["overflow"]>2:
            return rng.choice(ACTIONS)
        vals=[s["q"][a] for a in ACTIONS]
        return max(ACTIONS,key=lambda a:vals[a] - (0.25 if a in s["avoid"] else 0))
    def observe(self,s,p,a,r,m,c,t):
        s["counts"][a]+=1
        s["q"][a] += (r-s["q"][a])/s["counts"][a]
        # Detect mismatch patterns
        if m>0.20 and r<0:
            s["overflow"] += 1.0
            s["debug_events"].append("metric-mismatch")
            s["criterion_mode"]="suspect"
        if r<-0.10:
            s["overflow"] += 0.7
            s["avoid"].add(a)
        # delayed/threshold detection: weak early signals + later improvement
        if t>=3 and abs(r)<0.05:
            s["overflow"] += 0.05
        if r>0.25 and s["counts"][a]>=3:
            s["overflow"] = max(0, s["overflow"]-0.4)
        # relation clue from signature; use only if repeated
        pol_sig, temp_sig, obj_sig, dyn_sig, comp_sig = c
        if pol_sig==-1:
            s["relation"]="possible-reverse"
        if temp_sig in (-1,0):
            s["temporal"]="possible-delayed/threshold"
        if obj_sig==1:
            s["criterion_mode"]="possible-misleading"
        # deeper overflow: revise criteria/model
        if s["overflow"]>=2.8 and s["revisions"]<1:
            s["revisions"]+=1
            self.revision_count+=1
            s["criterion_mode"]="objective"
            s["model"]="factorized"
            self.meta_changes+=1
        if s["overflow"]>=4.2 and s["revisions"]<2:
            s["revisions"]+=1
            self.revision_count+=1
            s["model"]="meta-factorized"
            self.designer_notes["deep-model-revision"]+=1
        if s["revisions"] and rng.random()<0.05:
            # occasional broader probe after revision
            s["avoid"].clear()
    def end(self,s,p,total,best_possible):
        self.meta[p.signature]["seen"] += 1
        if total >= best_possible*0.35:
            self.meta[p.signature]["success"] += 1
        # learn a profile, but weight by actual objective reward
        for a in ACTIONS:
            self.meta[p.signature]["strategy"][a] += 0.18*s["q"][a]
        self.meta[p.signature]["strategy"] = {a: v/((self.meta[p.signature]["seen"])**0.55) 
                                              for a,v in self.meta[p.signature]["strategy"].items()}

def run_episode(agent, planet, steps=14):
    state=agent.start(planet)
    total=0.0
    best_possible=steps*0.34
    streak_a=0
    used_b=False
    negative=0
    futile=0
    for t in range(steps):
        a=agent.choose(state,planet,t)
        r,m,c=env_step(planet,a,t,streak_a,used_b)
        if abs(r)<0.05: futile+=1
        if r<0: negative+=1
        if a==planet.target_a:
            streak_a+=1
        else:
            streak_a=0
        if a==planet.target_b:
            used_b=True
        total += r
        agent.observe(state,planet,a,r,m,c,t)
    agent.end(state,planet,total,best_possible)
    success = total >= 1.15
    return {"total":total,"success":success,"negative":negative,"futile":futile,
            "revisions":state.get("revisions",0),
            "overflow":state.get("overflow",0),
            "debug":len(state.get("debug_events",[]))}

import random, math, statistics
from dataclasses import dataclass
from collections import defaultdict, Counter

SEED=20260918
R=random.Random(SEED)
ACTIONS=range(6)

@dataclass
class Planet:
    pol:int      # +1 normal, -1 reverse
    temp:int     # 0 immediate, 1 delayed, 2 threshold
    mis:int      # misleading criterion?
    dyn:int      # dynamic?
    comp:int     # composite?
    sig:tuple
    a:int
    b:int
    switch:int

def make_planet(r):
    pol=r.choice([1,-1]); temp=r.randrange(3); mis=r.randrange(2); dyn=r.randrange(2); comp=r.randrange(2)
    raw=(pol,temp-1,1 if mis else -1,1 if dyn else -1,1 if comp else -1)
    sig=tuple(max(-1,min(1,v+(r.choice([-1,0,0,0,1]) if r.random()<.3 else 0))) for v in raw)
    a=r.randrange(6); b=r.choice([x for x in range(6) if x!=a])
    return Planet(pol,temp,mis,dyn,comp,sig,a,b,r.randint(6,9) if dyn else 99)

def step(p,a,t,streak,seen_b,r):
    active=p.a if t<p.switch else p.b
    if p.comp:
        if a in (p.a,p.b):
            reward=.10 if not seen_b else .28
        else: reward=-.10
    else:
        reward=.34 if a==active else -.08
        if p.pol==-1:
            if a==p.a: reward=-.26
            elif a==p.b: reward=.26
    if p.temp==1 and t<3: reward=0.0
    if p.temp==2:
        if a==p.a: reward=.04 if streak<3 else .42
        elif not p.comp: reward=-.05
    metric=reward+r.gauss(0,.07)
    if p.mis and a==p.a: metric=abs(metric)+.18
    return reward+r.gauss(0,.05),metric

class Base:
    name="Base"
    def __init__(self): self.g=defaultdict(dict)
    def start(self,p): return {"q":[0.0]*6,"n":[0]*6}
    def act(self,s,p,t):
        if random.random()<.2: return random.randrange(6)
        return max(range(6),key=lambda a:s["q"][a])
    def obs(self,s,p,a,r,m): 
        s["n"][a]+=1; s["q"][a]+=(r-s["q"][a])/s["n"][a]
    def end(self,s,p,total): pass

class Reflexion(Base):
    name="Reflexion"
    def start(self,p): return {"q":[0.0]*6,"n":[0]*6,"avoid":set()}
    def act(self,s,p,t):
        if t<2 or random.random()<.18:
            ch=[a for a in range(6) if a not in s["avoid"]]
            return random.choice(ch or list(range(6)))
        return max(range(6),key=lambda a:s["q"][a]-(.2 if a in s["avoid"] else 0))
    def obs(self,s,p,a,r,m):
        super().obs(s,p,a,r,m)
        if r<-.1: s["avoid"].add(a)

class Voyager(Base):
    name="Voyager"
    def start(self,p):
        skill=self.g.get(p.sig,[0.0]*6).copy()
        return {"q":[0.0]*6,"n":[0]*6,"skill":skill}
    def act(self,s,p,t):
        if random.random()<(.3 if t<5 else .12): return random.randrange(6)
        return max(range(6),key=lambda a:s["skill"][a]+.5*s["q"][a])
    def obs(self,s,p,a,r,m):
        super().obs(s,p,a,r,m); s["skill"][a]+=.12*r
    def end(self,s,p,total): self.g[p.sig]=s["skill"].copy()

class ADAS(Base):
    name="ADAS"
    def start(self,p): return {"q":[0.0]*6,"n":[0]*6,"mode":random.choice(["greedy","explore","switch"])}
    def act(self,s,p,t):
        if s["mode"]=="explore": return random.randrange(6)
        if s["mode"]=="switch": return (t+(1 if t>5 else 0))%6
        if random.random()<.15: return random.randrange(6)
        return max(range(6),key=lambda a:s["q"][a])
    def obs(self,s,p,a,r,m):
        super().obs(s,p,a,r,m)
        if sum(s["n"])>3 and sum(s["q"])/6<.05 and (sum(s["n"]) in (4,8)): s["mode"]=random.choice(["explore","switch"])

class DGM(Base):
    name="DGM"
    def __init__(self):
        self.eps=.24; self.switch=.3
    def start(self,p): return {"q":[0.0]*6,"n":[0]*6,"eps":max(.05,min(.5,self.eps+R.gauss(0,.04)))}
    def act(self,s,p,t):
        if random.random()<s["eps"]: return random.randrange(6)
        if p.dyn and t>=p.switch-1 and random.random()<self.switch: return random.randrange(6)
        return max(range(6),key=lambda a:s["q"][a])
    def obs(self,s,p,a,r,m): super().obs(s,p,a,r,m)
    def end(self,s,p,total):
        self.eps=min(.45,self.eps+.01) if total<1.2 else max(.10,self.eps-.004)

class Positive(Base):
    name="Positive"
    def __init__(self): self.meta=defaultdict(lambda: {"seen":0,"score":[0.0]*6}); self.notes=Counter()
    def start(self,p):
        return {"q":[0.0]*6,"n":[0]*6,"overflow":0.0,"rev":0,"criterion":"objective","model":"local","debug":0}
    def act(self,s,p,t):
        learned=self.meta[p.sig]["seen"]>=5
        if learned and random.random()<.65:
            prof=self.meta[p.sig]["score"]; 
            if random.random()<max(.06,.22-.02*min(7,s["overflow"])): return random.randrange(6)
            return max(range(6),key=lambda a:prof[a])
        if t<2 or s["overflow"]>2.5: return random.randrange(6)
        return max(range(6),key=lambda a:s["q"][a])
    def obs(self,s,p,a,r,m):
        super().obs(s,p,a,r,m)
        if m>.2 and r<0:
            s["overflow"]+=1; s["criterion"]="suspect"; s["debug"]+=1
        if r<-.1: s["overflow"]+=.7
        # clue-driven suspicion
        if p.sig[0]<0: s["overflow"]+=.05
        if p.sig[1] in (-1,0): s["overflow"]+=.03
        if s["overflow"]>=2.8 and s["rev"]<1:
            s["rev"]=1; s["model"]="factorized"; self.notes["criterion/model revision"]+=1
        if s["overflow"]>=4.2 and s["rev"]<2:
            s["rev"]=2; s["model"]="meta-factorized"; self.notes["designer warning"]+=1
    def end(self,s,p,total):
        m=self.meta[p.sig]; m["seen"]+=1
        for a in range(6): m["score"][a]=.86*m["score"][a]+.14*s["q"][a]

import random, time, math, statistics
from dataclasses import dataclass
from collections import defaultdict
import numpy as np, pandas as pd

SEED=424242
rnd=random.Random(SEED)

@dataclass(frozen=True)
class P2:
    pol:int         # 0 normal, 1 reverse
    temp:int        # 0 immediate, 1 delayed, 2 threshold
