# Improved Positive: meta-learns factor-specific modes; still starts weak.
class Positive3(Base2):
    name="Positive"
    def __init__(self):
        self.factor_pref=[defaultdict(lambda: np.zeros(6)) for _ in range(5)]
        self.seen=defaultdict(int)
        self.revisions=0
        self.designer_alerts=0
    def start(self,p):
        return {"q":[0.0]*6,"n":[0]*6,"overflow":0.0,"rev":0,
                "mode":"local","debug":0,"bad_recent":0}
    def act(self,s,p,t):
        # weak local probing
        if t<3:
            return rnd.randrange(6)
        # use learned factor evidence as clues, not exact truth
        vals=np.array(s["q"],dtype=float)
        sig=p.sig
        seen=self.seen[p.sig]
        # after enough cross-stage evidence, use factorized hypotheses
        if seen>=8:
            for j,v in enumerate(sig):
                vals += 0.85*self.factor_pref[j][v][:]
        # deeper overflow changes how we use evidence
        if s["rev"]>=1 and s["overflow"]>=2.2:
            # possible polarity reversal
            if sig[0]>0:
                vals[1] += 0.7
            # temporal clue
            if sig[1]==0:
                vals[2] += 0.9
            elif sig[1]>0:
                vals[3] += 1.0
            # misleading criterion -> verify
            if sig[2]>0:
                vals[4] += 0.8
            # composite -> favor compatible pair
            if sig[4]>0 and t%2==0: vals[0] += 0.55
            if sig[4]>0 and t%2==1: vals[4] += 0.55
        # dynamic switch is an explicit hypothesis only after enough evidence
        if seen>=12 and sig[3]>0 and t>=7:
            vals[5]+=1.5
